/** TV discovery, rather than a settings form: 24 cached records and six visible cards. */
final class VelaDiscoveryView extends FrameLayout implements AutoCloseable {
    interface Host {
        void load(int mode,int genre,int page);
        void open(VelaShows.Airing programme);
        void exit();void navigation();void focused();boolean header(View from);
    }
    private final Host host;private final TextView back,previous,next,count,message;
    private final TextView[] periods=new TextView[3],genres=new TextView[5];
    private final FrameLayout grid,overlay;private final List<Card> cards=new ArrayList<>();
    private final List<List<VelaShows.Airing>> groups=new ArrayList<>();
    private VelaProgrammeArt art;private VelaContentDetails sheet;private List<VelaShows.Airing> selected;
    private int mode,genre,batch,slice,ordinal,focused;private boolean loading,more,lastSlice,focusResults,closed,paused;
    private final Runnable minute=new Runnable(){public void run(){if(closed||paused)return;boolean ended=false;long now=System.currentTimeMillis()/1000;for(Card card:cards){card.time();ended|=card.programme.end<=now;}if(ended&&mode==0&&!loading&&sheet==null)request(false);postDelayed(this,60000-System.currentTimeMillis()%60000);}};
    VelaDiscoveryView(Context c,Host host,int mode,int genre,int batch){
        super(c);this.host=host;this.mode=mode;this.genre=genre;this.batch=batch;setClipChildren(false);
        TextView title=text(L10n.text("What to watch"),36,VelaTheme.WHITE);title.setTypeface(Ui.displaySemibold);put(this,title,80,18,1190,64);
        back=button("‹  "+L10n.text("Back to guide"),host::exit);put(this,back,1420,22,306,54);back.setOnKeyListener((v,k,e)->{if(!arrow(k))return false;if(e.getAction()==KeyEvent.ACTION_DOWN){if(k==KeyEvent.KEYCODE_DPAD_DOWN)periods[this.mode].requestFocus();else if(k==KeyEvent.KEYCODE_DPAD_UP){if(!host.header(v))host.navigation();}else if(k==KeyEvent.KEYCODE_DPAD_LEFT)host.navigation();}return true;});
        String[] time={"Now","Tonight","Next 48 hours"},types={"All","Movies","Sports","Documentaries","Kids"};
        for(int i=0;i<periods.length;i++){final int at=i;periods[i]=button(L10n.text(time[i]),()->filter(at,this.genre));put(this,periods[i],80+i*282,110,270,54);periods[i].setOnKeyListener((v,k,e)->filterKey(false,at,k,e));}
        for(int i=0;i<genres.length;i++){final int at=i;genres[i]=button(L10n.text(types[i]),()->filter(this.mode,at));put(this,genres[i],80+i*240,180,228,50);genres[i].setOnKeyListener((v,k,e)->filterKey(true,at,k,e));}
        grid=new FrameLayout(c);put(this,grid,80,256,1646,540);
        message=text("",24,VelaTheme.SECONDARY);message.setMaxLines(3);message.setGravity(Gravity.CENTER);put(this,message,180,388,1446,144);
        previous=button("‹  "+L10n.text("Previous"),()->page(-1));next=button(L10n.text("Next")+"  ›",()->page(1));put(this,previous,80,850,230,56);put(this,next,1496,850,230,56);count=text("",18,VelaTheme.SECONDARY);count.setGravity(Gravity.CENTER);put(this,count,650,852,500,52);
        for(TextView pager:new TextView[]{previous,next})pager.setOnKeyListener((v,k,e)->{if(!arrow(k))return false;if(e.getAction()==KeyEvent.ACTION_DOWN){if(k==KeyEvent.KEYCODE_DPAD_UP)focusCard(Math.min(focused,cards.size()-1));else if(k==KeyEvent.KEYCODE_DPAD_LEFT){if(v==next&&previous.isEnabled())previous.requestFocus();else host.navigation();}else if(k==KeyEvent.KEYCODE_DPAD_RIGHT&&next.isEnabled())next.requestFocus();}return true;});
        overlay=new FrameLayout(c);overlay.setBackground(VelaContentDetails.programmeScrim());overlay.setVisibility(GONE);put(this,overlay,0,0,1790,940);request(false);
    }
    private TextView text(String label,int size,int color){TextView v=new TextView(getContext());v.setText(label);v.setTextSize(TypedValue.COMPLEX_UNIT_PX,size*VelaReading.scale(getContext()));v.setTypeface(Ui.medium);v.setTextColor(color);v.setIncludeFontPadding(false);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private void put(FrameLayout root,View v,int x,int y,int w,int h){LayoutParams p=new LayoutParams(w,h);p.leftMargin=x;p.topMargin=y;root.addView(v,p);}
    private TextView button(String label,Runnable action){TextView v=text(label,18,VelaTheme.WHITE);v.setId(View.generateViewId());v.setGravity(Gravity.CENTER);v.setPadding(12,6,12,6);v.setSingleLine();v.setEllipsize(TextUtils.TruncateAt.END);v.setFocusable(true);v.setFocusableInTouchMode(true);v.setDefaultFocusHighlightEnabled(false);v.setBackground(VelaTheme.shape(VelaTheme.CARD,18));v.setOnFocusChangeListener((w,f)->{if(f)host.focused();skin();});v.setOnClickListener(w->action.run());return v;}
    private boolean arrow(int k){return k>=KeyEvent.KEYCODE_DPAD_UP&&k<=KeyEvent.KEYCODE_DPAD_RIGHT;}
    private boolean filterKey(boolean type,int at,int key,KeyEvent event){if(!arrow(key))return false;if(event.getAction()==KeyEvent.ACTION_DOWN){TextView[] row=type?genres:periods;if(key==KeyEvent.KEYCODE_DPAD_LEFT){if(at==0)host.navigation();else row[at-1].requestFocus();}else if(key==KeyEvent.KEYCODE_DPAD_RIGHT)row[Math.min(row.length-1,at+1)].requestFocus();else if(key==KeyEvent.KEYCODE_DPAD_UP){if(type)periods[mode].requestFocus();else back.requestFocus();}else if(type){if(!cards.isEmpty())focusCard(0);else if(next.isEnabled())next.requestFocus();}else genres[genre].requestFocus();}return true;}
    private void filter(int mode,int genre){if(this.mode==mode&&this.genre==genre&&!loading)return;this.mode=mode;this.genre=genre;batch=slice=ordinal=focused=0;request(false);}
    private void skin(){for(int row=0;row<2;row++){TextView[] all=row==0?periods:genres;for(int i=0;i<all.length;i++)if(all[i]!=null){boolean f=all[i].hasFocus(),on=i==(row==0?mode:genre);all[i].setTextColor(f?VelaTheme.INK:VelaTheme.WHITE);all[i].setBackground(VelaTheme.shape(f?VelaReading.accent(getContext()):on?VelaTheme.RAISED:VelaTheme.CARD,18));all[i].setSelected(on);}}for(TextView v:new TextView[]{back,previous,next})if(v!=null){v.setTextColor(v.hasFocus()?VelaTheme.INK:VelaTheme.WHITE);v.setBackground(VelaTheme.shape(v.hasFocus()?VelaReading.accent(getContext()):VelaTheme.CARD,18));}}
    void focusFirst(){periods[mode].requestFocus();}
    private void request(boolean focus){if(closed||paused)return;focusResults=focus;loading=true;groups.clear();more=false;if(art!=null)art.clear();grid.removeAllViews();cards.clear();message.setText(L10n.text("Loading programmes…"));message.setVisibility(VISIBLE);pager();skin();host.load(mode,genre,batch);}
    void accept(List<VelaShows.Airing> raw){if(closed||paused)return;loading=false;more=raw.size()>=24;Map<String,List<VelaShows.Airing>> grouped=new LinkedHashMap<>();for(int i=0;i<Math.min(24,raw.size());i++){VelaShows.Airing p=raw.get(i);String key=p.start+"|"+p.end+"|"+(p.eventId.isEmpty()?VelaWorkspace.normal(p.title)+"|"+TvChannelNames.match(p.channel):p.eventId);grouped.computeIfAbsent(key,k->new ArrayList<>()).add(p);}groups.clear();groups.addAll(grouped.values());if(lastSlice){slice=Math.max(0,(groups.size()-1)/6);lastSlice=false;}slice=Math.max(0,Math.min(slice,Math.max(0,(groups.size()-1)/6)));if(sheet==null)render();else pager();}
    void error(String text){if(closed)return;loading=false;message.setText(text);message.setVisibility(VISIBLE);pager();if(sheet!=null)sheet.hint(text);}
    private VelaProgrammeArt art(){if(art==null)art=new VelaProgrammeArt(getContext(),this);return art;}
    private void render(){if(closed||paused)return;if(art!=null)art.clear();grid.removeAllViews();cards.clear();message.setVisibility(groups.isEmpty()?VISIBLE:GONE);message.setText(L10n.text("No matching broadcasts in the saved guide. Change the filter or refresh Television."));int start=slice*6;for(int i=start;i<Math.min(start+6,groups.size());i++){Card card=new Card(groups.get(i),i-start);put(grid,card,(i-start)%2*832,(i-start)/2*184,814,172);cards.add(card);card.bind();}pager();if(focusResults&&!cards.isEmpty())focusCard(Math.min(focused,cards.size()-1));focusResults=false;}
    private void pager(){boolean before=!loading&&(batch>0||slice>0),after=!loading&&(slice*6+6<groups.size()||more);previous.setEnabled(before);previous.setFocusable(before);previous.setAlpha(before?1:.3f);next.setEnabled(after);next.setFocusable(after);next.setAlpha(after?1:.3f);count.setText(loading?"":L10n.text("Page")+" "+(ordinal+1));}
    private void page(int direction){if(loading)return;ordinal=Math.max(0,ordinal+direction);focused=0;if(direction>0&&slice*6+6<groups.size()){slice++;focusResults=true;render();}else if(direction<0&&slice>0){slice--;focusResults=true;render();}else if(direction>0&&more){batch++;slice=0;request(true);}else if(direction<0&&batch>0){batch--;lastSlice=true;request(true);}}
    private void focusCard(int index){if(cards.isEmpty()){genres[genre].requestFocus();return;}cards.get(Math.max(0,Math.min(index,cards.size()-1))).requestFocus();}
    private final class Card extends FrameLayout {
        final List<VelaShows.Airing> variants;final VelaShows.Airing programme;final int index;final TextView title,channel,timing;final ImageView image;final ProgressBar progress;private int left=-1;
        Card(List<VelaShows.Airing> variants,int index){super(VelaDiscoveryView.this.getContext());this.variants=variants;programme=variants.get(0);this.index=index;setId(View.generateViewId());setFocusable(true);setFocusableInTouchMode(true);setDefaultFocusHighlightEnabled(false);setBackground(VelaTheme.shape(VelaTheme.CARD,20));image=new ImageView(getContext()){@Override public void setImageDrawable(Drawable d){super.setImageDrawable(d);place();}@Override public void setImageBitmap(Bitmap b){super.setImageBitmap(b);place();}};image.setScaleType(ImageView.ScaleType.FIT_CENTER);put(this,image,18,32,156,108);title=text(programme.title,24,VelaTheme.WHITE);title.setTypeface(Ui.displaySemibold);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);addView(title);channel=text(programme.channel+(variants.size()>1?"  +"+(variants.size()-1):""),18,VelaTheme.SECONDARY);channel.setSingleLine();channel.setEllipsize(TextUtils.TruncateAt.END);addView(channel);timing=text("",17,VelaTheme.SECONDARY);timing.setSingleLine();timing.setEllipsize(TextUtils.TruncateAt.END);addView(timing);progress=new ProgressBar(getContext(),null,android.R.attr.progressBarStyleHorizontal);progress.setMax(1000);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(VelaReading.accent(getContext())));progress.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(VelaTheme.LINE));put(this,progress,20,166,774,3);place();time();setOnFocusChangeListener((v,f)->{if(f){focused=index;host.focused();}setBackground(VelaTheme.shape(f?VelaReading.accent(getContext()):VelaTheme.CARD,20));title.setTextColor(f?VelaTheme.INK:VelaTheme.WHITE);for(TextView label:new TextView[]{channel,timing})label.setTextColor(f?0xFF626773:VelaTheme.SECONDARY);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(f?VelaTheme.INK:VelaReading.accent(getContext())));});setOnClickListener(v->show(variants));setOnKeyListener((v,k,e)->{if(!arrow(k))return false;if(e.getAction()==KeyEvent.ACTION_DOWN){if(k==KeyEvent.KEYCODE_DPAD_LEFT){if(index%2==0)host.navigation();else focusCard(index-1);}else if(k==KeyEvent.KEYCODE_DPAD_RIGHT)focusCard(index%2==0&&index+1<cards.size()?index+1:index);else if(k==KeyEvent.KEYCODE_DPAD_UP){if(index<2)genres[genre].requestFocus();else focusCard(index-2);}else if(index+2<cards.size())focusCard(index+2);else if(next.isEnabled())next.requestFocus();else if(previous.isEnabled())previous.requestFocus();}return true;});}
        void place(){if(title==null)return;int x=image.getDrawable()==null?20:194;if(left==x)return;left=x;for(View v:new View[]{title,channel,timing}){LayoutParams p=new LayoutParams(794-x,v==title?82:28);p.leftMargin=x;p.topMargin=v==title?12:v==channel?100:132;v.setLayoutParams(p);}}
        void bind(){String source=programme.image.isEmpty()?programme.logo:programme.image;if(!VelaProgrammeArt.url(source).isEmpty())art().bind(image,source,256,144);}
        void time(){long now=System.currentTimeMillis()/1000;String from=new SimpleDateFormat("HH:mm",Ui.locale()).format(new Date(programme.start*1000));timing.setText(programme.start<=now&&programme.end>now?L10n.text("On now")+" · "+remaining((programme.end-now+59)/60):from+" · "+L10n.text(programme.end<=now?"Ended":"Upcoming"));progress.setProgress((int)(1000*Math.max(0,Math.min(1,(double)(now-programme.start)/Math.max(1,programme.end-programme.start)))));progress.setVisibility(programme.start<=now?VISIBLE:INVISIBLE);setContentDescription(programme.title+", "+programme.channel+", "+timing.getText());}
    }
    void show(VelaShows.Airing p){show(Collections.singletonList(p));}
    private static String remaining(long minutes){return L10n.text("Remaining ")+(minutes>60?minutes/60+" h"+(minutes%60==0?"":" "+minutes%60+" min"):minutes+" min");}
    private void show(List<VelaShows.Airing> variants){if(closed)return;choosing=false;selected=new ArrayList<>(variants);if(art!=null)art.clear();overlay.removeAllViews();overlay.setVisibility(VISIBLE);VelaShows.Airing p=variants.get(0);String time=new SimpleDateFormat("EEE d HH:mm",Ui.locale()).format(new Date(p.start*1000));sheet=new VelaContentDetails(getContext(),p.title,p.channel+" · "+time,p.description,-1);String image=VelaProgrammeArt.url(p.image.isEmpty()?p.logo:p.image);sheet.broadcast(!image.isEmpty());put(overlay,sheet,200,120,1390,660);if(!image.isEmpty())art().bind(sheet.image,image);long now=System.currentTimeMillis()/1000;sheet.notice(L10n.text(p.start<=now&&p.end>now?"On now":p.end<=now?"Ended":"Upcoming"));TextView open=sheet.action(L10n.text(variants.size()>1?"Choose a channel":"Watch channel live"),"",()->{if(variants.size()>1)channels(variants);else host.open(p);});TextView[] save={null},follow={null};save[0]=sheet.action(L10n.text(VelaWatchlist.contains(getContext(),VelaWatchlist.airingId(p))?"Remove from Watch later":"Save for later"),"",()->{try{VelaWatchlist.toggle(getContext(),VelaWatchlist.airing(p));sheet.updateAction(save[0],L10n.text(VelaWatchlist.contains(getContext(),VelaWatchlist.airingId(p))?"Remove from Watch later":"Save for later"));sheet.hint(L10n.text("Watch later updated"));}catch(Exception unavailable){sheet.hint(L10n.text("Could not save this item."));}});follow[0]=sheet.action(L10n.text(VelaShows.follows(getContext(),p.title)?"Stop following":"Follow programme"),"",()->{VelaShows.toggle(getContext(),p.title);VelaShows.remember(getContext(),variants);sheet.updateAction(follow[0],L10n.text(VelaShows.follows(getContext(),p.title)?"Stop following":"Follow programme"));});sheet.action(L10n.text("Back"),"",this::dismiss);open.requestFocus();}
    private boolean choosing;
    private void channels(List<VelaShows.Airing> group){choosing=true;if(art!=null)art.clear();overlay.removeAllViews();VelaShows.Airing p=group.get(0);sheet=new VelaContentDetails(getContext(),p.title,L10n.text("Choose a channel"),p.description,-1);sheet.broadcast(false);sheet.listActions();put(overlay,sheet,200,120,1390,660);for(VelaShows.Airing station:group)sheet.action(station.channel,"",()->host.open(station));sheet.actions.getChildAt(0).requestFocus();}
    private void dismiss(){choosing=false;selected=null;sheet=null;overlay.setVisibility(GONE);overlay.removeAllViews();render();focusCard(focused);}
    boolean back(){if(sheet==null)return false;if(choosing){choosing=false;show(selected);}else dismiss();return true;}
    void pause(){paused=true;removeCallbacks(minute);if(art!=null){art.close();art=null;}}
    void resume(){if(closed)return;paused=false;if(selected!=null){show(selected);if(loading)host.load(mode,genre,batch);}else if(loading)request(false);else render();removeCallbacks(minute);postDelayed(minute,60000-System.currentTimeMillis()%60000);}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();removeCallbacks(minute);postDelayed(minute,60000-System.currentTimeMillis()%60000);}
    @Override protected void onDetachedFromWindow(){removeCallbacks(minute);super.onDetachedFromWindow();}
    @Override public void close(){if(closed)return;closed=true;pause();groups.clear();cards.clear();selected=null;overlay.removeAllViews();grid.removeAllViews();}
}
